insert into public.site_content(key,value) values('insurance','{"title":"Protegemos tus negocios. Aseguramos tu crecimiento.","subtitle":"Soluciones de seguros para empresas, constructoras, profesionales y personas. Asesoría especializada para proteger operaciones, patrimonio y proyectos.","cta":"SOLICITAR ASESORÍA EN SEGUROS","highlights":["Seguros corporativos","Responsabilidad Civil","Empresas constructoras","Licitaciones y garantías","Seguros de vida y ahorro","Seguros marítimos","Protección patrimonial"],"guaranteesTitle":"¿Tu empresa necesita presentar garantías para una licitación?","guaranteesText":"Conversemos sobre las alternativas disponibles.","notice":"Información y orientación comercial. No constituye una cotización ni una aprobación de cobertura. Las coberturas efectivas dependen de las condiciones generales y particulares, exclusiones, deducibles, límites asegurados, evaluación del riesgo y aceptación de la compañía aseguradora. La contratación e intermediación quedan sujetas a la verificación de las habilitaciones correspondientes.","responsible":"roxana","roxana":{"name":"Roxana Ximena Oyarzún Bustamante","role":"Experta en Negocios y Seguros Corporativos | Encargada del Área de Seguros BKO","description":"Profesional especializada en el área de negocios y seguros corporativos, encargada de desarrollar soluciones de protección y gestión de riesgos para empresas, constructoras y personas.\n\nSu trabajo se orienta especialmente a la asesoría en Responsabilidad Civil, seguros para empresas constructoras, coberturas para licitaciones, protección de maquinaria, seguros de vida y soluciones aseguradoras para actividades marítimas y comerciales.\n\nDesde BKO, lidera el desarrollo del área de seguros, proporcionando orientación para identificar necesidades de cobertura y encontrar alternativas acordes con las características de cada actividad económica.","image":"assets/personas/roxana-367.webp","specialties":["Responsabilidad Civil","Seguros para empresas","Seguros para constructoras","Garantías para licitaciones","Seguros de maquinaria","Seguros de vida y ahorro","Protección de pagos","Seguros marítimos y embarcaciones"]},"groups":[{"id":"responsabilidad-civil","title":"Responsabilidad Civil — Protección para empresas","description":"Los riesgos asociados a las actividades empresariales pueden generar daños a terceros y responsabilidades económicas. Contar con una cobertura adecuada permite enfrentar estas contingencias de acuerdo con las condiciones de la póliza contratada.","note":""},{"id":"constructoras","title":"Seguros para empresas constructoras","description":"Protección para obras, maquinaria, trabajadores y contratos.","note":"La exigencia de seguros depende de las bases de licitación, los contratos y los mandantes; no todos los seguros son obligatorios en todas las obras."},{"id":"garantias","title":"Garantías y seguros para licitaciones","description":"Facilitamos el acceso a garantías para que tu empresa pueda participar y ejecutar nuevos proyectos.","note":"Alternativas de garantías que pueden ayudar a optimizar el uso de las líneas de crédito bancarias de las empresas. La aceptación del instrumento depende de las bases de licitación, el contrato y las condiciones del beneficiario."},{"id":"vida-ahorro","title":"Protección personal y planificación financiera","description":"Orientación para evaluar necesidades de protección personal y ahorro previsional.","note":"Los beneficios tributarios del APV dependen del régimen elegido y de la normativa vigente. No se garantiza rentabilidad ni un beneficio tributario individual."},{"id":"cesantia","title":"Seguros de cesantía y protección de pagos","description":"Información y alternativas de respaldo financiero ante el desempleo.","note":"El Seguro de Cesantía obligatorio administrado por AFC es un sistema legal de protección social; no es un producto comercial ofrecido por BKO. Los seguros complementarios son productos distintos y están sujetos a sus propias condiciones."},{"id":"maritimos","title":"Seguros marítimos y embarcaciones","description":"Orientación conectada con la presencia de BKO en Puerto Varas y su área marítima y naviera.","note":"Las coberturas se evalúan según el uso, las características de la embarcación, la operación y la aceptación de la aseguradora."}],"services":[{"id":"rc-general","group":"responsabilidad-civil","title":"Responsabilidad Civil General","category":"Responsabilidad Civil","description":"Cobertura de daños corporales y materiales causados a terceros como consecuencia de la actividad de una empresa, conforme a las condiciones y exclusiones de la póliza.","risks":["Accidentes de clientes o visitantes","Daños materiales a terceros","Incidentes relacionados con operaciones comerciales"],"order":0,"active":true,"image":"","imageAlt":"","cta":"SOLICITAR ASESORÍA","informational":false},{"id":"rc-empresas","group":"responsabilidad-civil","title":"Responsabilidad Civil para Empresas","category":"Seguros Empresariales","description":"Soluciones para empresas de distintos tamaños y actividades económicas.","risks":["Predios y operaciones","Productos","Contratistas y subcontratistas","Actividades empresariales"],"order":1,"active":true,"image":"assets/oficinas/santiago/WhatsApp%20Image%202026-11-05%20at%2022.48.40.jpeg","imageAlt":"Sala de reuniones de la oficina BKO en Santiago","cta":"SOLICITAR ASESORÍA","informational":false},{"id":"rc-profesional","group":"responsabilidad-civil","title":"Responsabilidad Civil Profesional","category":"Responsabilidad Civil","description":"Orientada a profesionales y empresas que prestan servicios especializados. Considera reclamaciones derivadas de errores u omisiones profesionales, de acuerdo con los términos contratados.","risks":["Abogados","Arquitectos e ingenieros","Contadores y consultores"],"order":2,"active":true,"image":"","imageAlt":"","cta":"SOLICITAR ASESORÍA","informational":false},{"id":"rc-cruzada","group":"responsabilidad-civil","title":"Responsabilidad Civil Cruzada","category":"Responsabilidad Civil","description":"Especialmente relevante en construcción y proyectos con distintas empresas. Permite contemplar reclamaciones entre asegurados bajo las condiciones específicas de la póliza.","risks":["Proyectos con múltiples participantes","Reclamaciones entre asegurados"],"order":3,"active":true,"image":"","imageAlt":"","cta":"SOLICITAR ASESORÍA","informational":false},{"id":"rc-patronal","group":"responsabilidad-civil","title":"Responsabilidad Civil Patronal","category":"Responsabilidad Civil","description":"Cobertura relacionada con reclamaciones de responsabilidad civil derivadas de accidentes laborales sufridos por trabajadores, conforme a los términos y condiciones contratados.","risks":["Reclamaciones por accidentes laborales"],"order":4,"active":true,"image":"","imageAlt":"","cta":"SOLICITAR ASESORÍA","informational":false},{"id":"rc-contaminacion","group":"responsabilidad-civil","title":"Responsabilidad Civil por Contaminación","category":"Responsabilidad Civil","description":"Soluciones para riesgos relacionados con contaminación y daños ambientales, según el alcance de la cobertura.","risks":["Incidentes que puedan afectar suelos","Daños a recursos hídricos"],"order":5,"active":true,"image":"","imageAlt":"","cta":"SOLICITAR ASESORÍA","informational":false},{"id":"todo-riesgo","group":"constructoras","title":"Todo Riesgo Construcción","category":"Construcción","description":"Coberturas para proyectos durante su ejecución. Los siguientes riesgos son posibles riesgos asegurables, sujetos a las condiciones de la póliza.","risks":["Incendio","Sismo, cuando esté contemplado","Robo de materiales, según condiciones","Daños por agua","Daños accidentales durante la construcción","Otros riesgos contemplados en la póliza"],"order":6,"active":true,"image":"","imageAlt":"","cta":"SOLICITAR ASESORÍA","informational":false},{"id":"rc-construccion","group":"constructoras","title":"Responsabilidad Civil Construcción","category":"Construcción","description":"Protección frente a reclamaciones por daños a terceros durante la ejecución de obras.","risks":["Daños a propiedades colindantes y vecinos","Accidentes de transeúntes","Caída de materiales","Daños derivados de excavaciones"],"order":7,"active":true,"image":"","imageAlt":"","cta":"SOLICITAR ASESORÍA","informational":false},{"id":"equipos","group":"constructoras","title":"Equipos y Maquinaria","category":"Maquinaria","description":"Soluciones que pueden considerar daños propios, robo y responsabilidad civil asociada, según cada producto.","risks":["Retroexcavadoras y grúas","Camiones y generadores","Equipos industriales","Maquinaria de construcción"],"order":8,"active":true,"image":"assets/oficinas/calama/WhatsApp%20Image%202026-11-05%20at%2022.51.17.jpeg","imageAlt":"Vehículo de servicios industriales junto al acceso de BKO en Calama","cta":"SOLICITAR ASESORÍA","informational":false},{"id":"accidentes-obras","group":"constructoras","title":"Accidentes Personales para Trabajadores","category":"Construcción","description":"Alternativas de protección complementaria para trabajadores de proyectos y faenas.","risks":["Muerte accidental, cuando esté contemplada","Invalidez, según el seguro contratado"],"order":9,"active":true,"image":"","imageAlt":"","cta":"SOLICITAR ASESORÍA","informational":false},{"id":"seriedad","group":"garantias","title":"Garantía de Seriedad de la Oferta","category":"Licitaciones y Garantías","description":"Instrumentos destinados a respaldar el compromiso del oferente durante un proceso de licitación.","risks":["Participación en licitaciones","Compromiso del oferente"],"order":10,"active":true,"image":"","imageAlt":"","cta":"SOLICITAR ASESORÍA","informational":false},{"id":"fiel-cumplimiento","group":"garantias","title":"Garantía de Fiel Cumplimiento","category":"Licitaciones y Garantías","description":"Garantías destinadas a respaldar el cumplimiento de las obligaciones contractuales.","risks":["Ejecución de contratos","Obligaciones frente al beneficiario"],"order":11,"active":true,"image":"","imageAlt":"","cta":"SOLICITAR ASESORÍA","informational":false},{"id":"correcta-ejecucion","group":"garantias","title":"Garantía de Correcta Ejecución","category":"Licitaciones y Garantías","description":"Soluciones relacionadas con obligaciones posteriores a la ejecución de obras, incluyendo los mecanismos de garantía establecidos en las bases y contratos.","risks":["Obligaciones posteriores a la obra","Condiciones de las bases y contratos"],"order":12,"active":true,"image":"","imageAlt":"","cta":"SOLICITAR ASESORÍA","informational":false},{"id":"seguro-garantia","group":"garantias","title":"Seguro de Garantía","category":"Licitaciones y Garantías","description":"Un seguro de garantía es emitido por una compañía aseguradora y se rige por las condiciones de su póliza. Una boleta bancaria es emitida por un banco. Son instrumentos distintos: el seguro no equivale jurídicamente a una boleta bancaria en todos los casos y su aceptación debe revisarse en cada licitación y contrato.","risks":["Evaluación de alternativas de garantías","Uso de líneas de crédito bancarias"],"order":13,"active":true,"image":"","imageAlt":"","cta":"SOLICITAR ASESORÍA","informational":false},{"id":"vida-ahorro","group":"vida-ahorro","title":"Seguro de Vida con Ahorro","category":"Vida y Ahorro","description":"Protección por fallecimiento junto con una alternativa de acumulación de ahorro, según las condiciones del producto.","risks":["Protección familiar","Acumulación de ahorro sujeta al producto"],"order":14,"active":true,"image":"","imageAlt":"","cta":"SOLICITAR ASESORÍA","informational":false},{"id":"apv","group":"vida-ahorro","title":"APV — Ahorro Previsional Voluntario","category":"APV","description":"Alternativas de ahorro previsional voluntario para complementar la jubilación. Los regímenes tributarios tienen tratamientos distintos al aportar y al retirar; sus beneficios dependen de la elección y de la normativa vigente.","risks":["Complementar el ahorro previsional","Evaluación del régimen tributario"],"order":15,"active":true,"image":"","imageAlt":"","cta":"SOLICITAR ASESORÍA","informational":false},{"id":"vida-temporal","group":"vida-ahorro","title":"Seguro de Vida Temporal","category":"Vida y Ahorro","description":"Protección económica por un período determinado para personas y familias que necesitan respaldo financiero.","risks":["Protección por fallecimiento durante el período contratado"],"order":16,"active":true,"image":"","imageAlt":"","cta":"SOLICITAR ASESORÍA","informational":false},{"id":"afc","group":"cesantia","title":"Seguro de Cesantía Obligatorio — AFC","category":"Cesantía","description":"Sistema legal de protección económica ante la cesantía para las personas trabajadoras comprendidas por la normativa chilena, administrado por AFC y sujeto a requisitos legales de acceso. Información referencial: BKO no comercializa este sistema.","risks":["Consultar afiliación y beneficios directamente en AFC"],"order":17,"active":true,"image":"","imageAlt":"","cta":"SOLICITAR ASESORÍA","informational":true},{"id":"cesantia-complementaria","group":"cesantia","title":"Seguro de Cesantía Complementario","category":"Cesantía","description":"Alternativas de protección financiera frente a situaciones de desempleo, conforme al producto y sus requisitos.","risks":["Respaldo económico ante desempleo cubierto"],"order":18,"active":true,"image":"","imageAlt":"","cta":"SOLICITAR ASESORÍA","informational":false},{"id":"pagos","group":"cesantia","title":"Protección de Pagos","category":"Cesantía","description":"Soluciones asociadas a determinados créditos y obligaciones financieras que pueden cubrir cuotas durante períodos de cesantía, conforme a los términos contratados.","risks":["Cuotas y obligaciones financieras elegibles"],"order":19,"active":true,"image":"","imageAlt":"","cta":"SOLICITAR ASESORÍA","informational":false},{"id":"colectivos","group":"cesantia","title":"Seguros Colectivos","category":"Seguros Empresariales","description":"Alternativas de protección para trabajadores como parte de los beneficios empresariales, cuando exista un producto adecuado.","risks":["Beneficios para equipos de trabajo","Condiciones de adhesión y cobertura"],"order":20,"active":true,"image":"","imageAlt":"","cta":"SOLICITAR ASESORÍA","informational":false},{"id":"casco","group":"maritimos","title":"Casco y Maquinaria de Embarcaciones","category":"Embarcaciones","description":"Alternativas de cobertura para embarcaciones y su maquinaria, sujetas a los eventos cubiertos por la póliza.","risks":["Incendio y colisión","Varadura y robo","Daños derivados de eventos cubiertos"],"order":21,"active":true,"image":"","imageAlt":"","cta":"SOLICITAR ASESORÍA","informational":false},{"id":"rc-maritima","group":"maritimos","title":"Responsabilidad Civil Marítima","category":"Responsabilidad Civil Marítima","description":"Protección frente a reclamaciones por daños a otras embarcaciones, instalaciones portuarias o personas, de acuerdo con la póliza.","risks":["Daños a terceros vinculados a la operación marítima"],"order":22,"active":true,"image":"","imageAlt":"","cta":"SOLICITAR ASESORÍA","informational":false},{"id":"accidentes-bordo","group":"maritimos","title":"Accidentes Personales para Tripulantes y Pasajeros","category":"Embarcaciones","description":"Alternativas de cobertura para personas a bordo, según las condiciones contratadas.","risks":["Tripulantes","Pasajeros"],"order":23,"active":true,"image":"","imageAlt":"","cta":"SOLICITAR ASESORÍA","informational":false},{"id":"trabajo-maritimo","group":"maritimos","title":"Embarcaciones de Trabajo","category":"Embarcaciones","description":"Soluciones según el uso y actividad comercial de cada embarcación.","risks":["Pesca","Turismo","Transporte","Actividades comerciales"],"order":24,"active":true,"image":"assets/oficinas/puerto%20varas/WhatsApp%20Image%202026-11-05%20at%2022.48.53.jpeg","imageAlt":"Entorno lacustre visto desde la terraza de BKO en Puerto Varas","cta":"SOLICITAR ASESORÍA","informational":false}]}'::jsonb) on conflict(key) do nothing;
